      try{await navigator.clipboard.writeText(copyText);if(copyPrompt){hand.copied=true;hand.copyStatus='已复制。下一步打开 ChatGPT，粘贴并发送。';el.textContent='已复制 ✓ 再复制一次';el.closest('li').classList.add('done');document.getElementById('exam-copy-status').textContent=hand.copyStatus;}else{hand.fixStatus='修正请求已复制，请发回刚才的 ChatGPT 对话。';el.textContent='已复制 ✓';document.getElementById('exam-fix-status').textContent=hand.fixStatus;}}
      catch(_){var ta=document.getElementById(copyPrompt?'exam-prompt-text':'exam-fix-text');if(copyPrompt)hand.showText=true;else hand.showFix=true;if(ta){ta.closest('details').open=true;ta.focus();ta.select();}var statusText='浏览器拦截了自动复制，文字已在下面全选，请手动复制。';if(copyPrompt)hand.copyStatus=statusText;else hand.fixStatus=statusText;var statusEl=document.getElementById(copyPrompt?'exam-copy-status':'exam-fix-status');if(statusEl)statusEl.textContent=statusText;}
