  document.addEventListener('change',async function(event){if(!['exam-grade-file','exam-backup-file'].includes(event.target.id))return;var target=event.target,f=target.files[0],r=current();if(!f)return;try{if(f.size>8*1024*1024)throw Error('文件过大，请选择8MB以内的评分或模拟考试备份。');var raw=await f.text();if(target.id==='exam-grade-file'){if(r!==current()||!r||r.channel!=='manual'||r.grade)return;handState(r).reply=raw;document.getElementById('exam-grade-json').value=raw;}else{if(active())throw Error('当前仍有未提交的考试，请先提交后再恢复备份。');var staged=validateBackup(JSON.parse(raw));root.MockExams._restore=staged;dialog('<h2>恢复模拟考试备份？</h2><p>将替换此处的'+records.length+'份模拟记录，导入'+staged.length+'份。教材笔记和原刷题记录不受影响。建议先导出当前模拟备份。</p>'+btn('确认恢复','restore-confirm',''));}}catch(err){var box=target.id==='exam-grade-file'&&document.getElementById('exam-import-error');if(box){var hand=handState(r);hand.error=err.message;hand.fix=E.fixRequest(err.message);box.innerHTML=handoffError(hand);}else{message=err.message;rerender();}}finally{target.value='';}});
  function tick(){var r=active();if(r){lastNow=now();if(E.remaining(r.paper,now())<=0&&r.status==='running')submit(r,true);else if(r.status==='running'&&r.channel==='auto'&&Date.now()%8000<1000)sync(r);}updateLive();if(Date.now()-lastProbe>20000&&(r||document.getElementById('mock-exam')))probe();records.filter(function(v){return v.status==='grading';}).slice(0,1).forEach(function(v){if(Date.now()%4000<1000)poll(v);});}
